import os
from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement, parse_xml
from docx.oxml.ns import nsdecls, qn
from docx.shared import Pt


def zh(s: str) -> str:
    return s.encode("utf-8").decode("unicode_escape")


def clear_document(doc: Document) -> None:
    body = doc._element.body
    for child in list(body):
        if child.tag.endswith("sectPr"):
            continue
        body.remove(child)


def add_text_paragraph(doc: Document, text: str, bold: bool = False, center: bool = False) -> None:
    p = doc.add_paragraph()
    if center:
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run(text)
    run.bold = bold
    font = run.font
    font.name = "SimSun"
    font.size = Pt(12)
    rpr = run._element.get_or_add_rPr()
    rpr.append(parse_xml(r"<w:rFonts %s w:ascii='Times New Roman' w:hAnsi='Times New Roman' w:eastAsia='宋体'/>" % nsdecls("w")))
    pf = p.paragraph_format
    pf.space_before = Pt(0)
    pf.space_after = Pt(0)
    pf.line_spacing = 1.25


def _set_run_fonts(run, ascii_font: str = "Times New Roman", east_asia_font: str = "SimSun") -> None:
    font = run.font
    font.name = ascii_font
    font.size = Pt(12)
    rpr = run._element.get_or_add_rPr()
    r_fonts = OxmlElement("w:rFonts")
    r_fonts.set(qn("w:ascii"), ascii_font)
    r_fonts.set(qn("w:hAnsi"), ascii_font)
    r_fonts.set(qn("w:eastAsia"), east_asia_font)
    rpr.append(r_fonts)


def _math_run(text: str):
    mr = OxmlElement("m:r")
    mt = OxmlElement("m:t")
    mt.text = text
    mr.append(mt)
    return mr


def _math_box(text: str, tag: str):
    node = OxmlElement(tag)
    node.append(_math_run(text))
    return node


def _math_sub(base: str, sub: str):
    node = OxmlElement("m:sSub")
    e = OxmlElement("m:e")
    e.append(_math_run(base))
    s = OxmlElement("m:sub")
    s.append(_math_run(sub))
    node.append(e)
    node.append(s)
    return node


def _math_subsup(base: str, sub: str, sup: str):
    node = OxmlElement("m:sSubSup")
    e = OxmlElement("m:e")
    e.append(_math_run(base))
    sub_node = OxmlElement("m:sub")
    sub_node.append(_math_run(sub))
    sup_node = OxmlElement("m:sup")
    sup_node.append(_math_run(sup))
    node.append(e)
    node.append(sub_node)
    node.append(sup_node)
    return node


def _math_fraction(num_text: str, den_text: str):
    node = OxmlElement("m:f")
    num = OxmlElement("m:num")
    den = OxmlElement("m:den")
    num.append(_math_run(num_text))
    den.append(_math_run(den_text))
    node.append(num)
    node.append(den)
    return node


def add_math_paragraph(doc: Document, builder) -> None:
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    pf = p.paragraph_format
    pf.space_before = Pt(0)
    pf.space_after = Pt(0)
    pf.line_spacing = 1.25
    omath_para = OxmlElement("m:oMathPara")
    omath = OxmlElement("m:oMath")
    for node in builder():
        omath.append(node)
    omath_para.append(omath)
    p._element.append(omath_para)


def add_mixed_paragraph(doc: Document, parts) -> None:
    p = doc.add_paragraph()
    pf = p.paragraph_format
    pf.space_before = Pt(0)
    pf.space_after = Pt(0)
    pf.line_spacing = 1.25
    for part in parts:
        kind = part[0]
        if kind == "text":
            run = p.add_run(part[1])
            _set_run_fonts(run)
        elif kind == "math":
            omath = OxmlElement("m:oMath")
            for node in part[1]():
                omath.append(node)
            p._p.append(omath)
        else:
            raise ValueError(f"Unsupported paragraph part: {kind}")


def build_r_req_formula():
    return [
        _math_sub("R", "req"),
        _math_run("="),
        _math_run("d(p,s)"),
        _math_run("+"),
        _math_run("d(s,e)"),
        _math_run("+"),
        _math_run("d(e,p)"),
    ]


def build_cost_formula():
    return [
        _math_run("C"),
        _math_run("="),
        _math_sub("w", "t"),
        _math_run("T"),
        _math_run("+"),
        _math_sub("w", "u"),
        _math_sub("E", "u"),
        _math_run("+"),
        _math_sub("w", "a"),
        _math_sub("E", "a"),
        _math_run("+"),
        _math_sub("w", "c"),
        _math_sub("E", "c"),
        _math_run("+"),
        _math_sub("w", "w"),
        _math_sub("P", "w"),
        _math_run("+"),
        _math_sub("w", "o"),
        _math_sub("P", "o"),
        _math_run("+"),
        _math_sub("w", "f"),
        _math_sub("P", "f"),
    ]


